-- Périmètres géographiques disponibles pour CivicCare Tunis.
--
-- CONSTAT VÉRIFIÉ (Overpass + Nominatim, 2026-09-08) : OpenStreetMap ne contient PAS de
-- relation administrative municipale pour Tunis (seuls existent le pays admin_level=2,
-- le gouvernorat de Tunis relation 1435835 admin_level=4, et un « Lac de Tunis » niveau 6).
-- La relation 8896976 (« Tunis », place=city, Wikidata Q3572) est une emprise
-- d'AGGLOMÉRATION : vérification par points de référence, elle inclut Carthage,
-- Sidi Bou Saïd, La Marsa et Le Bardo (communes distinctes) et exclut l'Ariana et
-- Ben Arous. Elle ne doit donc PAS être qualifiée de limite municipale.
--
-- En conséquence (spécification §6.2) : le périmètre ACTIF par défaut est DEMO_TUNIS,
-- un polygone de démonstration dessiné manuellement, explicitement non officiel et
-- remplaçable, approximant la commune de Tunis (exclut Le Bardo par une encoche ouest,
-- Carthage/La Goulette/La Marsa à l'est, l'Ariana au nord, Ben Arous au sud).
-- Le passage en production est bloqué tant qu'un contour vérifié n'est pas configuré.
CREATE TABLE boundary
(
    id      uuid PRIMARY KEY,
    code    varchar(40)  NOT NULL UNIQUE,
    name_fr varchar(200) NOT NULL,
    name_ar varchar(200) NOT NULL,
    source  varchar(400) NOT NULL,
    license varchar(120) NOT NULL,
    is_demo boolean      NOT NULL,
    geom    geometry(MultiPolygon, 4326) NOT NULL
);
CREATE INDEX idx_boundary_geom ON boundary USING gist (geom);

INSERT INTO boundary (id, code, name_fr, name_ar, source, license, is_demo, geom)
VALUES ('b0000000-0000-0000-0000-000000000002', 'DEMO_TUNIS',
